function makeAudio(s){const a=new Audio(s.file);a._baseVolume=Math.max(0,Math.min(1,Number(s.volume??.95)));a.volume=a._baseVolume*state.master;const speed=Math.max(.5,Math.min(2,Number(s.speed??1))),pitch=Math.max(.5,Math.min(2,Number(s.pitch??1)));a.playbackRate=Math.max(.25,Math.min(4,speed*pitch));try{a.preservesPitch=false}catch{};return a}
function stopAll(){state.delayedTimers.forEach(t=>clearTimeout(t));state.delayedTimers=[];state.activeAudios.forEach(a=>{try{if(a._fadeTimer)clearInterval(a._fadeTimer);a.pause();a.currentTime=0}catch{}});state.activeAudios=[];stopDeck("A");stopDeck("B");toast("■ Tutti i suoni fermati")}
