function addQueue(s){if(!s)return;state.queue.push(s.id);renderQueue();scheduleProgressSave();toast("➕ "+s.name+" in coda")}
function playSound(s,vol=1){if(!s)return;if($("stopOthers")?.checked||s.stopOthers)stopAll();const start=()=>{const a=makeAudio(s),target=Math.min(1,a._baseVolume*state.master*vol),fadeIn=Math.max(0,Number(s.fadeIn||0)),fadeOut=Math.max(0,Number(s.fadeOut||0)),loops=Math.max(1,Math.round(Number(s.loops||1)));a.volume=fadeIn?0:target;a._loopsDone=1;state.lastAudio=a;state.lastSound=s;state.activeAudios.push(a);a.onended=()=>{state.activeAudios=state.activeAudios.filter(x=>x!==a);if(state.loop||a._loopsDone<loops){a._loopsDone++;a.currentTime=0;a.play().catch(()=>{});return}playNextQueue()};a.play().then(()=>{const sid=String(s.id);featureStats.plays[sid]=(featureStats.plays[sid]||0)+1;featureStats.history.push({time:Date.now(),id:sid,name:s.name});if(featureStats.history.length>200)featureStats.history.shift();localStorage.setItem("dsb_feature_stats",JSON.stringify(featureStats));if(featureState.statsEnabled!==false){try{if("Notification"in window&&Notification.permission==="granted")new Notification("VYBEX",{body:"▶ "+s.name})}catch{}};toast("▶ "+s.name);if(fadeIn){let i=0,n=Math.max(1,Math.round(fadeIn*20));a._fadeTimer=setInterval(()=>{i++;a.volume=target*i/n;if(i>=n){clearInterval(a._fadeTimer);a._fadeTimer=null}},50)}}).catch(()=>toast("Audio non riproducibile."));if(fadeOut)a.addEventListener("timeupdate",()=>{if(a.duration&&isFinite(a.duration)&&a.duration-a.currentTime<=fadeOut)a.volume=target*Math.max(0,(a.duration-a.currentTime)/fadeOut)},{passive:true})};const delay=Math.max(0,Number(s.delay||0));if(delay){const t=setTimeout(()=>{state.delayedTimers=state.delayedTimers.filter(x=>x!==t);start()},delay*1000);state.delayedTimers.push(t);toast("⏳ "+s.name+" tra "+delay.toFixed(2)+"s")}else start()}
