function renderQueue(){const el=$("queueList");if(!el)return;el.innerHTML=state.queue.map((id,i)=>{const s=state.sounds.find(x=>x.id===id);return s?`<div class="queue-item"><span>${i+1}. ${esc(s.icon||"🔊")} ${esc(s.name)}</span><button class="ghost" data-q="${i}">×</button></div>`:""}).join("")||"<small>Nessun brano in coda.</small>";el.querySelectorAll("[data-q]").forEach(b=>b.onclick=()=>{state.queue.splice(+b.dataset.q,1);renderQueue();scheduleProgressSave()})}
