function renderTabs(){const cats=[['ALL',state.lang==='it'?'Tutti':'All'],...Array.from(new Set(state.sounds.map(s=>s.category))).map(c=>[c,c])];$("tabs").innerHTML=cats.map(([id,label])=>`<button class="tab ${state.category===id?'active':''}">${esc(label)}</button>`).join("");[...$("tabs").children].forEach((b,i)=>b.onclick=()=>{state.category=cats[i][0];renderTabs();renderGrid()})}
function renderGrid(){let list=state.category==='ALL'?state.sounds:state.sounds.filter(s=>s.category===state.category);if(state.filter)list=list.filter(s=>(s.name+' '+s.category).toLowerCase().includes(state.filter));if($("favoritesBtn")?.classList.contains("active-filter"))list=list.filter(s=>state.favorites.has(s.id));const hints=$("keyboardHints")?.checked!==false;$("grid").innerHTML=list.map(s=>`<article class="card ${state.favorites.has(s.id)?'fav':''}" data-id="${esc(s.id)}" tabindex="0"><button class="favorite" data-fav="${esc(s.id)}">${state.favorites.has(s.id)?'★':'☆'}</button><div class="icon">${s.icon||'🔊'}</div><div class="name">${esc(s.name)}</div><div class="meta">${esc(s.category)} · ${Math.round((s.volume??.95)*100)}%</div>${hints&&s.hotkey?`<div class="key">${esc(s.hotkey)}</div>`:''}${hints&&s.combo?`<div class="combo">${esc(s.combo)}</div>`:''}<div class="play">▶</div>${state.canEdit?`<button class="edit" title="Apri parametri" aria-label="Modifica ${esc(s.name)}" data-edit="${esc(s.id)}">✏️</button>`:''}</article>`).join('');[...$("grid").children].forEach(card=>{const s=list.find(x=>x.id===card.dataset.id);card.onclick=e=>{if(e.target.closest('.edit')||e.target.closest('.favorite'))return;playSound(s)};card.ondblclick=e=>{if(!e.target.closest('button'))toggleFavorite(s)};card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();playSound(s)}};const eb=card.querySelector('.edit');if(eb)eb.onclick=e=>{e.stopPropagation();editSound(s)};const fb=card.querySelector('.favorite');if(fb)fb.onclick=e=>{e.stopPropagation();toggleFavorite(s)}})}
let editingSound=null;const editPresets={custom:{},normal:{volume:.95,pitch:1,speed:1,fadeIn:0,fadeOut:0,loops:1,delay:0},soft:{volume:.55,pitch:.9,speed:.92,fadeIn:.15,fadeOut:.35,loops:1,delay:0},loud:{volume:1,pitch:1.02,speed:1,fadeIn:0,fadeOut:.05,loops:1,delay:0},fast:{volume:.9,pitch:1.05,speed:1.35,fadeIn:0,fadeOut:.1,loops:1,delay:0},slow:{volume:.9,pitch:.95,speed:.7,fadeIn:.2,fadeOut:.5,loops:1,delay:0},deep:{volume:.95,pitch:.65,speed:.9,fadeIn:.1,fadeOut:.3,loops:1,delay:0},high:{volume:.9,pitch:1.65,speed:1.05,fadeIn:0,fadeOut:.15,loops:1,delay:0},meme:{volume:1,pitch:1.3,speed:1.15,fadeIn:0,fadeOut:.1,loops:2,delay:0},cinematic:{volume:.85,pitch:.92,speed:.88,fadeIn:.8,fadeOut:1.2,loops:1,delay:.1}};
function syncEditSliders(){const v=+$('editVolume').value,p=+$('editPitch').value,sp=+$('editSpeed').value,fi=+$('editFadeIn').value,fo=+$('editFadeOut').value,lo=+$('editLoops').value,de=+$('editDelay').value;$('editVolume2').value=v;$('editPitch2').value=p;$('editSpeed2').value=sp;$('volumeOut').value=Math.round(v*100)+'%';$('volumeBig').textContent=Math.round(v*100)+'%';$('pitchOut').value=p.toFixed(2)+'×';$('pitchBig').textContent=p.toFixed(2)+'×';$('speedOut').value=sp.toFixed(2)+'×';$('speedBig').textContent=sp.toFixed(2)+'×';$('fadeInOut').value=fi.toFixed(2)+'s';$('fadeOutOut').value=fo.toFixed(2)+'s';$('loopsOut').value=lo;$('delayOut').value=de.toFixed(2)+'s';$('previewIcon').textContent=$('editIcon').value||'🔊';$('previewName').textContent=$('editName').value||'Nome suono';$('previewMeta').textContent=`${$('editCategory').value||'Custom'} · ${Math.round(v*100)}% · ${sp.toFixed(2)}×`}
function openEditModal(s){if(!state.canEdit)return toast('Inserisci una email per modificare.');editingSound=s;$('editName').value=s.name||'';$('editCategory').value=s.category||'';$('editIcon').value=s.icon||'🔊';$('editTags').value=s.tags||'';$('editDescription').value=s.description||'';$('editHotkey').value=s.hotkey||'';$('editCombo').value=s.combo||'';$('editVolume').value=s.volume??.95;$('editPitch').value=s.pitch??1;$('editSpeed').value=s.speed??1;$('editFadeIn').value=s.fadeIn??0;$('editFadeOut').value=s.fadeOut??0;$('editLoops').value=s.loops??1;$('editDelay').value=s.delay??0;$('editFavorite').checked=state.favorites.has(s.id);$('editStopOthers').checked=!!s.stopOthers;$('editPreset').value='custom';syncEditSliders();$('editModal').hidden=false;$('editModal').setAttribute('aria-hidden','false');$('editName').focus()}
