function editPayload(){return{id:editingSound.id,name:$('editName').value.trim(),category:$('editCategory').value.trim()||'Other',icon:$('editIcon').value.trim()||'🔊',tags:$('editTags').value.trim(),description:$('editDescription').value.trim(),hotkey:$('editHotkey').value.trim(),combo:$('editCombo').value.trim(),volume:+$('editVolume').value,pitch:+$('editPitch').value,speed:+$('editSpeed').value,fadeIn:+$('editFadeIn').value,fadeOut:+$('editFadeOut').value,loops:+$('editLoops').value,delay:+$('editDelay').value,stopOthers:$('editStopOthers').checked}}
async function saveEditModal(e){e.preventDefault();if(!editingSound)return;const payload=editPayload();if(!payload.name)return toast('Inserisci un nome.');try{const r=await api('/api/sounds/update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const i=state.sounds.findIndex(x=>x.id===editingSound.id);if(i>=0)state.sounds[i]=r.sound;if($('editFavorite').checked)state.favorites.add(editingSound.id);else state.favorites.delete(editingSound.id);localStorage.setItem('dsb_favorites',JSON.stringify([...state.favorites]));scheduleProgressSave();renderTabs();renderGrid();fillDecks();closeEditModal();toast('💾 Parametri salvati.')}catch{toast('Modifica non riuscita.')}}
