function radioValues(field){return [...new Set(LOCAL_RADIOS.map(r=>r[field]).filter(Boolean))].sort((a,b)=>a.localeCompare(b))}
function setOptions(el,values,allLabel){el.innerHTML=`<option value="">${esc(allLabel)}</option>`+values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}
function syncRadioFilters(){
 const country=$('radioCountry').value;
 const regions=radioValues('region').filter(v=>!country||LOCAL_RADIOS.some(r=>r.country===country&&r.region===v));
 const oldRegion=$('radioRegion').value; setOptions($('radioRegion'),regions,'Tutte le regioni'); if(regions.includes(oldRegion))$('radioRegion').value=oldRegion;
 const region=$('radioRegion').value;
 const channels=radioValues('name').filter(v=>LOCAL_RADIOS.some(r=>(!country||r.country===country)&&(!region||r.region===region)&&r.name===v));
 const oldChannel=$('radioChannel').value; setOptions($('radioChannel'),channels,'Tutti i canali'); if(channels.includes(oldChannel))$('radioChannel').value=oldChannel;
 renderRadioList();
}
function renderRadioFilters(){
 setOptions($('radioCountry'),radioValues('country'),'Tutte le nazioni');
 setOptions($('radioRegion'),radioValues('region'),'Tutte le regioni');
 setOptions($('radioChannel'),radioValues('name'),'Tutti i canali');
 $('radioCountry').onchange=syncRadioFilters; $('radioRegion').onchange=syncRadioFilters; $('radioChannel').onchange=renderRadioList;
}
function stopRadio(){
 const a=$('radioAudio'); a.pause(); a.removeAttribute('src'); a.load(); $('radioFrame').src='about:blank'; $('radioFrame').hidden=true; $('radioAudio').hidden=true; $('radioPlayer').hidden=true;
 if('mediaSession' in navigator) navigator.mediaSession.playbackState='none';
}
function playRadio(r){
 stopRadio(); $('radioPlayer').hidden=false; $('radioNowName').textContent=r.name; $('radioNowMeta').textContent=`${r.city} · ${r.region} · ${r.country}`;
 const a=$('radioAudio'), frame=$('radioFrame');
 if(r.type==='audio'&&r.stream){
   a.hidden=false; a.src=r.stream; a.volume=.85; $('radioPlayerStatus').textContent="Riproduzione diretta nello stesso player dell'app.";
   a.play().then(()=>toast('▶ '+r.name)).catch(()=>{$('radioPlayerStatus').textContent='Premi Play nel player per avviare lo stream.'});
   if('mediaSession' in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:r.name,artist:r.city,album:'Radio locali'});navigator.mediaSession.playbackState='playing'}
 } else {
   frame.hidden=false; frame.src=r.url; $('radioPlayerStatus').textContent="Player ufficiale incorporato nell'app. Se l'emittente blocca l'incorporamento, il riquadro può restare vuoto.";
 }
}
function renderRadioList(){
 const country=$('radioCountry')?.value||'', region=$('radioRegion')?.value||'', channel=$('radioChannel')?.value||'', q=($('radioSearch')?.value||'').trim().toLowerCase();
 const list=LOCAL_RADIOS.filter(r=>(!country||r.country===country)&&(!region||r.region===region)&&(!channel||r.name===channel)&&(r.name+' '+r.city+' '+r.region+' '+r.country+' '+r.desc).toLowerCase().includes(q));
 $('radioList').innerHTML=list.map(r=>`<article class="radio-item"><div><strong>📻 ${esc(r.name)}</strong><span>${esc(r.city)} · ${esc(r.region)} · ${esc(r.country)}</span><p>${esc(r.desc)}</p></div><button class="primary" data-radio-id="${esc(r.name)}">▶ Ascolta in app</button></article>`).join('')||'<div class="radio-empty">Nessuna radio trovata con questi filtri.</div>';
 [...$('radioList').querySelectorAll('[data-radio-id]')].forEach(b=>b.onclick=()=>playRadio(LOCAL_RADIOS.find(x=>x.name===b.dataset.radioId)));
}

