function initFeatureHub(){if(!$('featureGroups'))return;const savedTheme=localStorage.getItem('dsb_theme');if(savedTheme)applyTheme(savedTheme);const bg=localStorage.getItem('dsb_bg');if(bg){document.body.style.backgroundImage=`url(${bg})`;document.body.style.backgroundSize='cover'}$('featureSearch').oninput=renderFeatures;$('featureCategory').onchange=renderFeatures;$('featuresExportBtn').onclick=()=>downloadJson('soundboard-settings.json',{features:featureState,scenes:state.scenes,favorites:[...state.favorites]});$('featuresImportBtn').onclick=()=>$('featuresImportFile').click();$('featuresImportFile').onchange=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);localStorage.setItem('dsb_100_features',JSON.stringify(d.features||d));Object.assign(featureState,d.features||d);if(d.scenes){state.scenes=d.scenes;localStorage.setItem('dsb_scenes',JSON.stringify(state.scenes));renderScenes()}if(Array.isArray(d.favorites)){state.favorites=new Set(d.favorites);localStorage.setItem('dsb_favorites',JSON.stringify(d.favorites));renderGrid()}renderFeatures();toast('📥 Impostazioni importate')}catch{toast('❌ JSON non valido')}};r.readAsText(f)};$('featuresFolderInput').onchange=async e=>{const files=[...e.target.files].filter(f=>/\.(wav|mp3|ogg|m4a)$/i.test(f.name));if(!state.canEdit){e.target.value='';return toast('Inserisci una email per importare una cartella.')}let ok=0;for(const f of files){const fd=new FormData();fd.append('file',f);try{const r=await api('/api/sounds/upload',{method:'POST',body:fd});state.sounds.push(r.sound);ok++}catch{}}state.category='ALL';renderTabs();renderGrid();fillDecks();e.target.value='';toast(`📂 Importati ${ok}/${files.length} file`)};$('featuresResetBtn').onclick=()=>{if(confirm('Ripristinare le 100 funzioni?')){Object.keys(featureState).forEach(k=>delete featureState[k]);saveFeatureState();renderFeatures();toast('↺ Funzioni ripristinate')}};$('panicFeatureBtn').onclick=()=>{stopAll();clearTimeout(state.timer);state.timer=null;toast('🛑 PANIC')};renderFeatures(); FEATURE_DEFS.forEach((f,i)=>{if(featureOn(featureId(i)))applyFeatureToggle(f[2],true)}); initMaker()}
